      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00055",
        "explanation": "Doctor explicitly identifies SpO2 <90% as a respiratory failure diagnostic standard and warns against home observation.",
        "quote": "您母亲目前静息不吸氧时血氧始终低于90，已经达到呼吸衰竭的诊断标准，结合黄痰、哮喘急性加重用药后缓解不明显，高度怀疑合并肺部感染，这种情况在家确实已经不能继续观察等待了"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00055",
        "explanation": "Doctor provides a concrete, respectful patient-facing script that separates immediate relief from the idea of long-term hospitalization.",
        "quote": "先把喘控制住，比在家硬扛舒服得多，越扛身体越累反而好不了。如果她还是坚决不同意，您现在就直接拨打120接去急诊，这是救命的情况，不能再等了。"
      }
    ]
  },
